// Generated by the studio: template 13's shared page behaviour.
function gdcInitT13(root) {
  'use strict';

  // ---- Mobile nav toggle ----
  var menu = root.querySelector(".mobile-menu");
  var hamburger = root.querySelector(".hamburger-button");
  var isMenuOpen = false;
  var readHeader = null;
  var setMenu = function (open) {
    if (!menu || !hamburger) return;
    menu.classList.toggle("is-open", open);
    hamburger.classList.toggle("is-open", open);
    hamburger.setAttribute("aria-expanded", open ? "true" : "false");
    isMenuOpen = open;
    if (readHeader) readHeader();
  };
  if (menu && hamburger) {
    hamburger.addEventListener("click", function () {
      setMenu(!menu.classList.contains("is-open"));
    });
  }

  // ---- Header: dark glass once the page scrolls (or while the mobile menu is open) ----
  var header = root.querySelector("[data-header]");
  if (header) {
    readHeader = function () {
      var y = window.scrollY || document.documentElement.scrollTop || 0;
      header.classList.toggle("is-scrolled", y > 8 || isMenuOpen);
    };
    window.addEventListener("scroll", readHeader, { passive: true });
    readHeader();
  }

  // ---- Scroll-to-top button, shown once the page has started scrolling ----
  var fab = root.querySelector("[data-to-top]");
  if (fab) {
    fab.addEventListener("click", function () { window.scrollTo({ top: 0, behavior: "smooth" }); });
    var fShown = null;
    var fTick = false;
    var fUpdate = function () {
      var on = (window.pageYOffset || document.documentElement.scrollTop) > 40;
      if (on === fShown) return;
      fShown = on;
      fab.classList.toggle("is-visible", on);
    };
    window.addEventListener("scroll", function () {
      if (fTick) return;
      fTick = true;
      requestAnimationFrame(function () { fTick = false; fUpdate(); });
    }, { passive: true });
    fUpdate();
  }

  // ---- Tabs (Fight Card page): [data-tabs] with role=tab links and role=tabpanel panels. Without JS every panel stays visible. ----
  root.querySelectorAll("[data-tabs]").forEach(function (card) {
    var tabs = Array.prototype.slice.call(card.querySelectorAll("[role=tab]"));
    var panels = Array.prototype.slice.call(card.querySelectorAll("[role=tabpanel]"));
    if (!tabs.length || tabs.length !== panels.length) return;
    var select = function (id, focus) {
      tabs.forEach(function (tab) {
        var on = tab.getAttribute("aria-controls") === id;
        tab.setAttribute("aria-selected", on ? "true" : "false");
        tab.tabIndex = on ? 0 : -1;
        if (on) {
          if (focus) tab.focus();
          var bar = tab.parentNode;
          bar.scrollLeft = tab.offsetLeft - (bar.clientWidth - tab.offsetWidth) / 2;
        }
      });
      panels.forEach(function (panel) { panel.hidden = panel.id !== id; });
    };
    var fromHash = function () {
      var id = (window.location.hash || "").slice(1);
      return panels.some(function (p) { return p.id === id; }) ? id : null;
    };
    tabs.forEach(function (tab, i) {
      tab.addEventListener("click", function (e) {
        e.preventDefault();
        var id = tab.getAttribute("aria-controls");
        select(id, false);
        if (window.history && window.history.replaceState) window.history.replaceState(null, "", "#" + id);
      });
      tab.addEventListener("keydown", function (e) {
        var n = null;
        if (e.key === "ArrowRight") n = (i + 1) % tabs.length;
        else if (e.key === "ArrowLeft") n = (i - 1 + tabs.length) % tabs.length;
        else if (e.key === "Home") n = 0;
        else if (e.key === "End") n = tabs.length - 1;
        if (n === null) return;
        e.preventDefault();
        select(tabs[n].getAttribute("aria-controls"), true);
      });
    });
    card.classList.add("is-tabbed");
    var first = fromHash();
    select(first || panels[0].id, false);
    if (first) {
      // The browser scrolls to the fragment itself once the page has loaded; scroll to the tab bar after that.
      var toBar = function () { window.setTimeout(function () { card.scrollIntoView(); }, 0); };
      if (document.readyState === "complete") toBar();
      else window.addEventListener("load", toBar);
    }
    window.addEventListener("hashchange", function () {
      var id = fromHash();
      if (id) { select(id, false); card.scrollIntoView(); }
    });
  });

  // ---- Table-of-contents scroll spy (Responsible gambling / Privacy / Terms) ----
  var tocLinks = root.querySelectorAll(".legal-toc-link");
  var headings = Array.prototype.slice.call(root.querySelectorAll("h2[id^='sec-']"));
  if (tocLinks.length && headings.length) {
    var onToc = function () {
      var current = headings[0].id;
      for (var i = 0; i < headings.length; i++) {
        if (headings[i].getBoundingClientRect().top <= 160) current = headings[i].id;
        else break;
      }
      tocLinks.forEach(function (a) {
        a.classList.toggle("is-active", a.getAttribute("href") === "#" + current);
      });
    };
    window.addEventListener("scroll", onToc, { passive: true });
    onToc();
  }
}
gdcInitT13(document);
